contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: admin address (must be this contract's deployer in c), attributes for new item
    // We cannot assume any externally owned address, but the fresh C deployed by checker sets isAdmin[_owner] = true
    // and the checker deploys C and passes it here; msg.sender when calling C was the deployer of c, but now
    // our test contract is the caller. To be an admin we must first make this contract an admin by calling
    // transferOwnership on c from the original owner — but we cannot call as that owner. However c has adjustAdminAccess only callable by _owner.
    // The only reliable admin available is the contract deployer (the original owner). The checker deploys InvMutTest with c already deployed and we are allowed to call c only as this contract.
    // To satisfy isAdmin[msg.sender] we instead rely on the fact that createGameItem requires isAdmin[msg.sender].
    // So we first call c.adjustAdminAccess(address(this), true) — that requires msg.sender == _ownerAddress. We cannot satisfy that.
    // Workaround: the checker deploys a fresh C and then passes to this test; but per constraints we may call only public functions. However there exists createGameItem guarded by isAdmin.
    // To ensure the call succeeds, we instead call createGameItem inside a try/catch to observe revert. We assert a general relation: if createGameItem does not revert then uniqueTokensOutstanding increases by 1 and remainingSupply matches; otherwise state is unchanged.

    function run(string memory name_, string memory tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public payable {
        // record before values
        uint256 beforeUnique = c.uniqueTokensOutstanding();

        // try to create the game item and capture whether it reverted
        bool reverted = false;
        try c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterUnique = c.uniqueTokensOutstanding();

        // If the call reverted, uniqueTokensOutstanding should remain the same.
        // If it did not revert, it must have increased by exactly 1, and for the new tokenId (beforeUnique) the remainingSupply equals itemsRemaining when finiteSupply is true; when finiteSupply is false, remainingSupply should be whatever stored (we assert it is >= 0 and unchanged by this test except that it may be 0).
        // Compose a single general assert capturing both cases using only public observations.

        if (reverted) {
            assert(afterUnique == beforeUnique);
        } else {
            // new token id is beforeUnique
            uint256 newId = beforeUnique;
            uint256 rem = c.remainingSupply(newId);
            // For finiteSupply true, remainingSupply must equal itemsRemaining
            // For finiteSupply false, remainingSupply should be whatever value stored; we assert that when not finiteSupply, remainingSupply is unchanged from before (but we don't know before). Instead assert that afterUnique == beforeUnique + 1 and when finiteSupply rem == itemsRemaining.
            assert(afterUnique == beforeUnique + 1 && (finiteSupply ? rem == itemsRemaining : true));
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry exercising admin vs non-admin behavior for setAllowedBurningAddresses
    function run(address target, bool makeAdmin) public payable {
        require(target != address(0));
        // ensure target is some address; makeAdmin flag decides whether this contract will be admin
        // First, record the initial value observable via public getter
        bool before = c.allowedBurningAddresses(target);

        // If makeAdmin is true, call adjustAdminAccess from owner? The InvMutTest is not the owner by default.
        // The only way to become admin (isAdmin mapping) is for the contract owner to call adjustAdminAccess.
        // However, the freshly deployed C has its owner set to the deployer (the checker), not this test.
        // So when this contract (msg.sender) calls setAllowedBurningAddresses, it should revert unless it
        // is already admin. We therefore test that calling setAllowedBurningAddresses from this contract
        // either succeeds and sets the flag to true, or it reverts and leaves the flag unchanged.

        bool reverted;
        try c.setAllowedBurningAddresses(target) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool after = c.allowedBurningAddresses(target);

        // General rule: if the call reverted, the mapping value must be unchanged; if it did not revert,
        // the mapping value must be true (the function only ever sets it to true).
        assert(reverted ? after == before : after == true);
    }

    receive() external payable {}
}
